function render(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/state.pageSize));state.page=Math.min(state.page,pages);const visible=state.paginationMode==='more'?rows.slice(0,state.shown):rows.slice((state.page-1)*state.pageSize,state.page*state.pageSize);$('#totalCount').textContent=state.characters.length.toLocaleString(state.lang);$('#visibleCount').textContent=rows.length.toLocaleString(state.lang);$('#characterGrid').innerHTML=visible.map(c=>`<article class="character-card" tabindex="0" data-id="${c.pageid}"><div class="card-image">${safeImage(c.thumbnail,c.title)}</div><div class="card-body"><h3>${esc(c.title)}</h3><p>${esc(c.extract||t('fallback'))}</p><div class="badges">${c.categories.slice(0,2).map(x=>`<span class="badge">${esc(translateCategory(x))}</span>`).join('')}</div></div></article>`).join('');$('#emptyState').hidden=rows.length>0;renderPagination(state.paginationMode==='more'?rows.length:pages);$('#activeFilters').innerHTML=[...state.selected].map(x=>`<button class="filter-pill" data-category="${esc(x)}">${esc(translateCategory(x))} ×</button>`).join('');renderAppliedFilters();document.querySelectorAll('.character-card').forEach(el=>{el.onclick=()=>openDetail(+el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter')openDetail(+el.dataset.id)}});document.querySelectorAll('.filter-pill').forEach(el=>el.onclick=()=>{state.selected.delete(el.dataset.category);state.page=1;state.shown=state.pageSize;renderFilters();render()});loadVisibleThumbnails(visible)}

function saveSession(){localStorage.setItem('cars-session',JSON.stringify({query:state.query,sort:state.sort,selected:[...state.selected]}))}
function applyPaginationLanguage(){const x={"pt-BR":['Por página','Navegação','Páginas','Mostrar mais','Personagens por página','Modo de navegação'],en:['Per page','Navigation','Pages','Show more','Characters per page','Navigation mode'],es:['Por página','Navegación','Páginas','Mostrar más','Personajes por página','Modo de navegación'],fr:['Par page','Navigation','Pages','Afficher plus','Personnages par page','Mode de navigation'],de:['Pro Seite','Navigation','Seiten','Mehr anzeigen','Figuren pro Seite','Navigationsmodus'],it:['Per pagina','Navigazione','Pagine','Mostra altro','Personaggi per pagina','Modalità di navigazione'],ja:['1ページあたり','ナビゲーション','ページ','もっと見る','1ページあたりのキャラクター数','ナビゲーションモード']}[state.lang]||['Per page','Navigation','Pages','Show more','Characters per page','Navigation mode'];$('#perPageLabel').textContent=x[0];$('#paginationModeLabel').textContent=x[1];$('#paginationModeSelect').options[0].textContent=x[2];$('#paginationModeSelect').options[1].textContent=x[3];$('#pageSizeSelect').setAttribute('aria-label',x[4]);$('#paginationModeSelect').setAttribute('aria-label',x[5])}
$('#searchInput').value=state.query;$('#sortSelect').value=state.sort;
applyPaginationLanguage();
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){state.query=e.target.value;saveSession()}},true);
document.addEventListener('change',e=>{if(e.target.id==='languageSelect')setTimeout(applyPaginationLanguage,0)},true);
document.addEventListener('change',e=>{if(e.target.id==='sortSelect'){state.sort=e.target.value;saveSession()}if(e.target.closest('#categoryFilters'))setTimeout(saveSession,0)},true);
document.addEventListener('click',e=>{if(e.target.closest('#clearFilters,.filter-pill,.applied-list button'))setTimeout(saveSession,0)},true);
document.addEventListener('click',e=>{const panel=$('.filters');if(panel?.classList.contains('mobile-open')&&!e.target.closest('.filters,#mobileFilterToggle'))panel.classList.remove('mobile-open')});
$('#detailDialog').addEventListener('close',()=>{if(state.detailReturnUrl!==null){history.replaceState(null,'',state.detailReturnUrl);state.detailReturnUrl=null}});
$('.brand').addEventListener('click',e=>{e.preventDefault();state.query='';state.sort='az';state.selected.clear();state.page=1;state.shown=state.pageSize;state.detailReturnUrl=null;$('#searchInput').value='';$('#sortSelect').value='az';$('.filters').classList.remove('mobile-open');document.querySelectorAll('dialog[open]').forEach(d=>d.close());history.replaceState(null,'',location.pathname+location.search);renderFilters();render();saveSession();window.scrollTo({top:0,behavior:'smooth'})});
init().then(()=>{if(location.hash==='#about'){$('#aboutDialog').showModal();return}if(location.hash){const title=decodeURIComponent(location.hash.slice(1)).replaceAll('_',' '),c=state.characters.find(x=>x.title===title);if(c)openDetail(c.pageid)}});
document.addEventListener('click',e=>{const button=e.target.closest('.gallery-expand');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const title=decodeURIComponent(location.hash.slice(1)).replaceAll('_',' '),character=state.characters.find(c=>c.title===title),images=character&&state.detailCache.get(character.pageid)?.images;if(!images?.length)return;const grid=button.closest('.gallery-content').querySelector('.photo-gallery'),expanded=button.dataset.expanded==='true',more={"pt-BR":'Ver todas as fotos',en:'View all photos',es:'Ver todas las fotos',fr:'Voir toutes les photos',de:'Alle Fotos anzeigen',it:'Vedi tutte le foto',ja:'すべての写真を見る'}[state.lang]||'View all photos',less={"pt-BR":'Mostrar menos fotos',en:'Show fewer photos',es:'Mostrar menos fotos',fr:'Afficher moins de photos',de:'Weniger Fotos anzeigen',it:'Mostra meno foto',ja:'写真を減らす'}[state.lang]||'Show fewer photos',photo=(im,i)=>`<button class="gallery-item" data-index="${i}"><img src="${esc(im.src)}" alt="${esc(im.alt||`${title} ${i+1}`)}" loading="lazy"><span>↗</span></button>`;if(expanded){grid.innerHTML=images.slice(0,2).map(photo).join('');grid.classList.add('gallery-preview');button.dataset.expanded='false';button.innerHTML=`${more} <strong>${images.length}</strong> ↓`}else{grid.innerHTML=images.map(photo).join('');grid.classList.remove('gallery-preview');button.dataset.expanded='true';button.textContent=`${less} ↑`}grid.querySelectorAll('.gallery-item').forEach(item=>item.onclick=()=>openViewer(images,+item.dataset.index,title))},true);
const navWords={"pt-BR":['Home','Orthos'],en:['Home','Orthos'],es:['Inicio','Orthos'],fr:['Accueil','Orthos'],de:['Startseite','Orthos'],it:['Home','Orthos'],ja:['ホーム','正投影']};function translateNav(){const x=navWords[state.lang]||navWords.en;$('#homeLink').textContent=x[0];$('#orthosLink').textContent=x[1]}translateNav();document.addEventListener('change',e=>{if(e.target.id==='languageSelect')setTimeout(translateNav,0)},true);document.querySelectorAll('#homeLink,#orthosLink').forEach(link=>link.addEventListener('click',()=>localStorage.removeItem('cars-session')));
